const routes=[['index.html','หน้าแรก'],['services.html','บริการและราคา'],['branches.html','สาขาของเรา'],['gallery.html','ผลงานของเรา'],['reviews.html','รีวิวลูกค้า'],['journal.html','สาระน่ารู้'],['contact.html','ติดต่อเรา']];
const file=location.pathname.split('/').pop()||'index.html';
const branches=[{name:'รามคำแหง 114',line:'@pamagrooming',url:'https://lin.ee/pBC80S0',phone:'0612593998',display:'061-259-3998',fb:'https://www.facebook.com/share/1BvY3Fd1as/?mibextid=wwXIfr'},{name:'พหลโยธิน 64',line:'@pama2',url:'https://lin.ee/Pa2GWJz',phone:'0842492255',display:'084-249-2255',fb:'https://www.facebook.com/share/1DqXrVfv5S/?mibextid=wwXIfr'}];
const images={hero:'https://images.unsplash.com/photo-1552053831-71594a27632d?auto=format&fit=crop&w=1000&q=85',dog:'https://images.unsplash.com/photo-1583337130417-3346a1be7dee?auto=format&fit=crop&w=700&q=85',cat:'https://images.unsplash.com/photo-1514888286974-6c03e2ca1dba?auto=format&fit=crop&w=700&q=85',stay:'https://images.unsplash.com/photo-1548199973-03cce0bbc87b?auto=format&fit=crop&w=700&q=85'};
const ext='target="_blank" rel="noopener noreferrer"';
const book='<button class="btn" data-book>จองคิวผ่าน LINE <span>↗</span></button>';
const maps=b=>'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent('PAMA Grooming '+b.name);
function branchCards(embed=false){return '<div class="branch-grid">'+branches.map((b,i)=>`<article class="branch"><span class="tag">PAMA GROOMING · BRANCH 0${i+1}</span><h3>สาขา${b.name}</h3><p>อาบน้ำ · ตัดขน · ฝากเลี้ยง สุนัขและแมว<br>เวลาเปิด–ปิด: กรุณาสอบถามสาขาผ่าน LINE</p><div class="contact"><a href="tel:${b.phone}">โทร ${b.display} ↗</a><a href="${b.url}" ${ext}>LINE ${b.line} ↗</a><a href="${b.fb}" ${ext}>Facebook สาขา${b.name} ↗</a></div><div class="actions"><a class="btn" href="${b.url}" ${ext}>จองคิวสาขานี้ ↗</a><a class="btn outline" href="${maps(b)}" ${ext}>ค้นหาแผนที่ ↗</a></div>${embed?`<iframe title="แผนที่ค้นหา PAMA Grooming ${b.name}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="https://maps.google.com/maps?q=${encodeURIComponent('PAMA Grooming '+b.name)}&output=embed"></iframe><p class="note">แผนที่แสดงผลการค้นหา กรุณายืนยันหมุดร้านกับสาขาก่อนเดินทาง</p>`:''}</article>`).join('')+'</div>'}
function serviceCards(){return `<div class="cards">${[['01','อาบน้ำ & ดูแลขน','สะอาด สดชื่น พร้อมกลับไปกอดกันอีกครั้ง สอบถามรายละเอียดบริการที่เหมาะกับน้องได้ทาง LINE',images.dog,'BATH & CARE'],['02','ตัดขน & จัดทรง','เลือกทรงที่ชอบ และพูดคุยเรื่องลักษณะขนกับทีมงานก่อนนัดหมาย',images.cat,'GROOM & STYLE'],['03','ฝากเลี้ยงสัตว์เลี้ยง','วางแผนวันรับ–ส่ง และสอบถามเงื่อนไขการเข้าพักกับสาขาที่สะดวก',images.stay,'PET BOARDING']].map(s=>`<article class="service"><img src="${s[3]}" alt="ภาพประกอบบริการ ${s[1]}" loading="lazy"><div class="body"><span class="num">${s[0]} / ${s[4]}</span><h3>${s[1]}</h3><p>${s[2]}</p><div class="row"><span>สอบถามราคาผ่าน LINE</span><a class="link" href="services.html">ดูรายละเอียด ↗</a></div></div></article>`).join('')}</div><p class="note">ภาพประกอบบรรยากาศ ไม่ใช่ภาพผลงานของร้าน</p>`}
function cta(){return `<div class="wrap section"><div class="callout"><div><h2>นัดวันดูแล ให้เจ้าตัวโปรด</h2><p>เลือกสาขาที่สะดวก แล้วทัก LINE เพื่อสอบถามราคาและคิวว่าง</p></div>${book}</div></div>`}
function gallery(){return `<div class="gallery">${[[images.dog,'ช่วงเวลาดี ๆ ของน้องหมา'],[images.cat,'ความน่ารักของเพื่อนตัวเล็ก'],[images.hero,'พร้อมสำหรับวันสดใส']].map(s=>`<figure><img src="${s[0]}" alt="ภาพประกอบสัตว์เลี้ยง" loading="lazy"><figcaption>${s[1]} · ภาพประกอบ</figcaption></figure>`).join('')}</div><div class="reviewbox" style="margin-top:28px"><h3>Before & After จาก PAMA</h3><p>กำลังเตรียมภาพผลงานจริงของแต่ละสาขา ระหว่างนี้ชมภาพล่าสุดและสอบถามตัวอย่างทรงขนได้ทาง Facebook ของร้าน</p><div class="branch-grid">${branches.map(b=>`<a class="link" href="${b.fb}" ${ext}>ชมผลงานสาขา${b.name} ↗</a>`).join('')}</div></div>`}
function reviews(){return `<div class="branch-grid">${branches.map(b=>`<article class="reviewbox"><span class="eyebrow">CUSTOMER STORIES</span><h3>สาขา${b.name}</h3><p>ดูความคิดเห็นจากลูกค้าบน Facebook ของสาขา<br>คะแนนและลิงก์รีวิว Google: อยู่ระหว่างยืนยันข้อมูล</p><a class="btn outline" href="${b.fb}" ${ext}>ดูความคิดเห็นบน Facebook ↗</a></article>`).join('')}</div>`}
const posts=[{slug:'prepare-grooming',title:'เตรียมตัวอย่างไร ก่อนพาน้องมาอาบน้ำตัดขน',cat:'GROOMING GUIDE',intro:'รายการเล็ก ๆ ที่ช่วยให้การนัดหมายเป็นเรื่องง่าย ทั้งสำหรับเจ้าของและเพื่อนตัวโปรด',body:'เริ่มจากเลือกสาขาที่สะดวก ส่งรูปน้องและแจ้งสายพันธุ์ น้ำหนักโดยประมาณ รวมถึงทรงขนที่อยากได้ผ่าน LINE จากนั้นสอบถามราคาและเวลาที่ใช้ก่อนยืนยันคิว หากน้องมีข้อจำกัดในการดูแลหรือไม่คุ้นกับการอาบน้ำ ให้แจ้งทีมงานล่วงหน้า เตรียมสายจูงหรือกระเป๋าสำหรับเดินทาง และยืนยันเวลารับ–ส่งกับสาขาอีกครั้ง'}, {slug:'coat-routine',title:'เปลี่ยนการดูแลขน ให้เป็นช่วงเวลาดี ๆ ที่บ้าน',cat:'EVERYDAY CARE',intro:'เริ่มจากกิจวัตรสั้น ๆ และเลือกอุปกรณ์ให้เหมาะกับลักษณะขนของน้อง',body:'เลือกหวีที่เหมาะกับลักษณะขน โดยสอบถามวิธีใช้จากช่างตัดขน เริ่มดูแลในช่วงที่น้องผ่อนคลาย ใช้เวลาสั้น ๆ และค่อย ๆ สร้างความคุ้นเคย หลีกเลี่ยงการดึงขนหรือฝืนเมื่อน้องไม่สบายตัว หากพบขนพันกันมาก ให้ช่างช่วยประเมินวิธีจัดการ และขอคำแนะนำสำหรับดูแลต่อที่บ้าน'}, {slug:'boarding-checklist',title:'เช็กลิสต์ก่อนฝากเลี้ยง ให้วันเดินทางสบายใจ',cat:'BOARDING CHECKLIST',intro:'เตรียมรายละเอียดกิจวัตรและของใช้ พร้อมพูดคุยเงื่อนไขกับสาขาก่อนเข้าพัก',body:'แจ้งวันฝากและวันรับ พร้อมสอบถามพื้นที่ว่างและค่าบริการกับสาขา เตรียมรายละเอียดอาหาร ปริมาณ และช่วงเวลาที่น้องคุ้นเคย รวมถึงข้อมูลติดต่อเจ้าของและผู้ติดต่อสำรอง สอบถามร้านว่าควรนำของใช้ใดมาบ้าง และยืนยันเงื่อนไขการรับฝาก เอกสารที่ต้องใช้ รวมถึงข้อจำกัดของบริการก่อนนัดหมาย'}];
function articles(){return `<div class="cards articles">${posts.map(p=>`<article><div class="label">${p.cat}</div><h3>${p.title}</h3><p>${p.intro}</p><a class="link" href="${p.slug}.html">อ่านบทความ ↗</a></article>`).join('')}</div>`}
function title(eyebrow,text,sub){return `<div class="wrap"><div class="page-title"><span class="eyebrow">${eyebrow}</span><h1>${text}</h1><p>${sub}</p></div></div>`}
let main='';let article=posts.find(p=>file===p.slug+'.html');
if(file==='index.html'){main=`<section class="wrap hero"><div><span class="eyebrow">A LITTLE CARE. A LOT OF LOVE.</span><h1>ดูแลด้วยใจ<br>ให้ทุกวันของน้อง<br>เป็นวันที่ดี <span style="color:#7da18a">♡</span></h1><p>PAMA GROOMING บริการอาบน้ำ ตัดขน และฝากเลี้ยง<br>สำหรับน้องหมาน้องแมว เพราะเพื่อนตัวเล็กของคุณ<br>ควรได้รับช่วงเวลาดี ๆ ในทุกครั้งที่มาเจอกัน</p><div class="actions">${book}<a href="services.html" class="btn outline">สำรวจบริการ ↗</a></div><div class="hero-note"><span>♧</span>ต้อนรับน้องหมาและน้องแมว · 2 สาขาในกรุงเทพฯ</div></div><div class="hero-visual"><div class="stamp">LITTLE PAWS<br>BIG LOVE<br>♡</div><img class="hero-image" src="${images.hero}" alt="ภาพประกอบสุนัขโกลเด้นรีทรีฟเวอร์"><div class="float"><span>♡</span><div><strong>ความสุข เริ่มจากการดูแล</strong><small>Bath · Grooming · Boarding</small></div></div><span class="image-label">ภาพประกอบ</span></div></section><div class="strip"><div class="wrap"><b>อาบน้ำ & ดูแลขน</b><i>✳</i><b>ตัดขน & จัดทรง</b><i>✳</i><b>ฝากเลี้ยงสัตว์เลี้ยง</b><i>✳</i><b>รามคำแหง 114 · พหลโยธิน 64</b></div></div><section class="wrap section"><div class="section-head"><div><span class="eyebrow">OUR SERVICES</span><h2>ทุกการดูแล เพื่อเพื่อนตัวโปรด</h2></div><a href="services.html" class="link">บริการและราคาทั้งหมด ↗</a></div>${serviceCards()}</section><section class="soft section"><div class="wrap story"><img src="${images.stay}" alt="ภาพประกอบสุนัขสองตัว" loading="lazy"><div><span class="eyebrow">HELLO, WE ARE PAMA</span><h2>เพราะน้องคือครอบครัว<br>การดูแลจึงมีความหมาย</h2><p>จากวันอาบน้ำ ไปจนถึงวันฝากเลี้ยง PAMA เป็นอีกหนึ่งจุดหมายสำหรับการดูแลเพื่อนสี่ขา เลือกบริการและพูดคุยกับสาขาที่สะดวก เพื่อเตรียมการดูแลให้เหมาะกับน้องของคุณ</p><div class="points"><div><strong>ครบทั้ง 3 บริการ</strong><small>อาบน้ำ ตัดขน และฝากเลี้ยง</small></div><div><strong>เลือกได้ 2 สาขา</strong><small>รามคำแหงและพหลโยธิน</small></div><div><strong>พูดคุยก่อนจอง</strong><small>แจ้งรายละเอียดผ่าน LINE OA</small></div><div><strong>สำหรับหมาและแมว</strong><small>สอบถามบริการที่เหมาะกับน้อง</small></div></div><p class="note">ภาพประกอบบรรยากาศ</p></div></div></section><section class="wrap section"><div class="section-head"><div><span class="eyebrow">FIND YOUR PAMA</span><h2>ใกล้บ้านคุณ ใกล้ใจน้อง</h2></div><p>เลือกสาขาที่สะดวก แล้วให้เราเป็นส่วนหนึ่ง<br>ของวันดี ๆ ของเพื่อนตัวเล็ก</p></div>${branchCards()}</section><section class="wrap section" style="padding-top:0"><div class="section-head"><div><span class="eyebrow">OUR LITTLE FRIENDS</span><h2>ความน่ารักที่อยากแบ่งปัน</h2></div><a class="link" href="gallery.html">ชมผลงานของเรา ↗</a></div>${gallery()}</section><section class="soft section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">FROM OUR CUSTOMERS</span><h2>เสียงจากครอบครัวของน้อง</h2></div><a class="link" href="reviews.html">ดูช่องทางรีวิว ↗</a></div>${reviews()}</div></section><section class="wrap section"><div class="section-head"><div><span class="eyebrow">THE PAMA JOURNAL</span><h2>เรื่องเล็ก ๆ เพื่อการดูแลที่ดี</h2></div><a class="link" href="journal.html">อ่านสาระน่ารู้ ↗</a></div>${articles()}</section>${cta()}`}
else if(file==='services.html'){main=title('BATH · GROOM · STAY','บริการและราคา','เลือกการดูแลที่เหมาะกับน้อง และสอบถามราคาจากสาขาก่อนจองคิว')+`<section class="wrap section" style="padding-top:15px">${serviceCards()}<div class="section-head" style="margin-top:55px"><h2>ค่าบริการสำหรับน้องหมาและแมว</h2></div><div class="tabs" role="tablist" aria-label="ประเภทสัตว์เลี้ยง"><button role="tab" class="tab selected" aria-selected="true" data-pet="สุนัข" aria-controls="prices">สุนัข</button><button role="tab" class="tab" aria-selected="false" data-pet="แมว" aria-controls="prices">แมว</button></div><div id="prices" role="tabpanel" class="tablebox" aria-live="polite"><table><thead><tr><th>บริการ</th><th>สัตว์เลี้ยง</th><th>ราคา</th></tr></thead><tbody>${['อาบน้ำ','ตัดขน','ฝากเลี้ยง / วัน'].map(s=>`<tr><td>${s}</td><td class="pet-label">สุนัข</td><td>สอบถามสาขาผ่าน LINE</td></tr>`).join('')}</tbody></table></div><p class="note">ยังไม่ได้เผยแพร่ราคาที่รับรองโดยร้าน กรุณาส่งรูปน้อง สายพันธุ์ น้ำหนัก และบริการที่ต้องการเพื่อขอราคาก่อนยืนยันคิว</p><div class="faq"><h3>ก่อนจองบริการ</h3><details open><summary>ราคาและเงื่อนไขบริการ</summary><p>สอบถามราคา รายการบริการที่รวมอยู่ และค่าใช้จ่ายเพิ่มเติมกับสาขาโดยตรง แจ้งลักษณะขน ขนพันกัน และข้อจำกัดในการดูแลก่อนจอง เพื่อให้ร้านประเมินรายละเอียดได้</p></details><details><summary>จองคิวอย่างไร?</summary><p>เลือกสาขา ทัก LINE OA แจ้งบริการและวันที่ต้องการ จากนั้นรอร้านยืนยันคิวและราคา การเปิดแชตยังไม่ถือเป็นการยืนยันการจอง</p></details><details><summary>ต้องเตรียมอะไรสำหรับฝากเลี้ยง?</summary><p>แจ้งวันเข้าพัก วันรับกลับ และกิจวัตรของน้อง สอบถามเงื่อนไข เอกสาร อาหารและของใช้ที่ต้องนำมาจากสาขาก่อนเข้าพัก</p></details></div></section>`+cta()}
else if(file==='branches.html'||file==='contact.html'){main=title(file==='contact.html'?'LET’S TALK':'OUR BRANCHES',file==='contact.html'?'คุยกับ PAMA ได้ที่นี่':'สาขาของเรา','ติดต่อ จองคิว และสอบถามรายละเอียดได้โดยตรงกับสาขาที่คุณสะดวก')+`<section class="wrap section" style="padding-top:15px">${branchCards(true)}</section>`+cta()}
else if(file==='gallery.html'){main=title('OUR LITTLE FRIENDS','ผลงานของเรา','พื้นที่สำหรับรวมภาพ Before & After และช่วงเวลาน่ารักของน้องหมาน้องแมว')+`<section class="wrap section" style="padding-top:15px">${gallery()}</section>`+cta()}
else if(file==='reviews.html'){main=title('CUSTOMER STORIES','รีวิวจากลูกค้า','ติดตามความคิดเห็นจากลูกค้าผ่านช่องทางของแต่ละสาขา')+`<section class="wrap section" style="padding-top:15px">${reviews()}<p class="note">เราจะเพิ่มรีวิวจริง คะแนน Google และลิงก์รีวิวรายสาขาหลังยืนยันแหล่งข้อมูล ไม่แสดงคะแนนหรือข้อความรีวิวที่สมมติขึ้น</p></section>`+cta()}
else if(file==='journal.html'){main=title('THE PAMA JOURNAL','สาระน่ารู้','แนวทางเตรียมตัวและกิจวัตรง่าย ๆ สำหรับเจ้าของสัตว์เลี้ยง')+`<section class="wrap section" style="padding-top:15px">${articles()}</section>`+cta()}
else if(article){main=title(article.cat,article.title,article.intro)+`<article class="wrap section" style="padding-top:15px"><div style="max-width:760px;font-size:17px;line-height:2.2">${article.body.split(' จากนั้น ').map(t=>`<p style="margin-bottom:24px">${t}</p>`).join('')}<a href="journal.html" class="link">← กลับไปสาระน่ารู้</a></div></article>`+cta()}
else{main=title('PAMA GROOMING','ไม่พบหน้านี้','กลับหน้าแรกเพื่อเลือกบริการหรือสาขาที่ต้องการ')+'<div class="wrap section"><a class="btn" href="index.html">กลับหน้าแรก</a></div>'}
document.getElementById('app').innerHTML=`<div class="top">PAMA GROOMING &nbsp; · &nbsp; BATH, GROOM & BOARDING &nbsp; · &nbsp; ดูแลเพื่อนตัวโปรดของคุณ</div><header><div class="wrap nav"><a class="logo" href="index.html" aria-label="PAMA Grooming หน้าแรก">PAMA<span class="paw">♧</span><small>GROOMING & CARE</small></a><button class="menu" aria-label="เปิดเมนู" aria-expanded="false" aria-controls="navigation">☰</button><nav id="navigation" aria-label="เมนูหลัก">${routes.map(r=>`<a href="${r[0]}" class="${file===r[0]?'active':''}" ${file===r[0]?'aria-current="page"':''}>${r[1]}</a>`).join('')}</nav>${book}</div></header><main>${main}</main><footer><div class="wrap"><div class="footer-grid"><div><a class="logo" href="index.html" style="color:var(--green);font-size:28px">PAMA<small>GROOMING & CARE</small></a><p style="margin-top:20px">ดูแลด้วยใจ ให้ทุกวันของน้องเป็นวันที่ดี<br>อาบน้ำ · ตัดขน · ฝากเลี้ยง สุนัขและแมว</p></div><div><h4>สำรวจ PAMA</h4>${routes.slice(1,4).map(r=>`<a href="${r[0]}">${r[1]}</a>`).join('')}<a href="journal.html">สาระน่ารู้</a></div>${branches.map(b=>`<div><h4>${b.name}</h4><a href="tel:${b.phone}">${b.display}</a><a href="${b.url}" ${ext}>LINE ${b.line}</a><a href="${b.fb}" ${ext}>Facebook ↗</a></div>`).join('')}</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} PAMA GROOMING. All rights reserved.</span><span>Made for little paws, with a lot of love. ♡</span></div></div></footer><button class="btn book-float" data-book>จองคิวผ่าน LINE ↗</button><dialog aria-labelledby="booking-title"><button class="close" aria-label="ปิดหน้าต่าง">×</button><span class="eyebrow">LET’S MAKE A DATE</span><h3 id="booking-title">เลือกสาขาที่สะดวก</h3><p>ทัก LINE เพื่อสอบถามราคาและคิวว่าง<br>การจองจะสมบูรณ์เมื่อสาขายืนยันกับคุณ</p>${branches.map(b=>`<a class="btn" href="${b.url}" ${ext}>${b.name} · ${b.line} ↗</a>`).join('')}</dialog>`;
const dialog=document.querySelector('dialog');document.querySelectorAll('[data-book]').forEach(b=>b.addEventListener('click',()=>{dialog.showModal();document.body.classList.add('locked')}));dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.classList.remove('locked'));dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('.menu').onclick=function(){const open=document.querySelector('nav').classList.toggle('open');this.setAttribute('aria-expanded',String(open));this.textContent=open?'×':'☰'};
document.querySelectorAll('[data-pet]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-pet]').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-selected',String(t===b))});document.querySelectorAll('.pet-label').forEach(t=>t.textContent=b.dataset.pet)});
